import asyncio
import json
import copy
from typing import Any, Dict, Optional, FrozenSet

# IoT Device Firmware - Configuration Manager
# Handles OTA config updates via MQTT-like protocol

_IMMUTABLE_KEYS: FrozenSet[str] = frozenset({
    "auth_required", "allowed_commands", "update_url",
    "firmware_version", "debug_mode"
})

_ALLOWED_CONFIG_KEYS: FrozenSet[str] = frozenset({
    "network", "dns", "primary", "secondary", "hostname",
    "interval", "timeout", "retries", "max_retries",
    "display", "brightness", "locale", "timezone"
})


class DeviceRegistry:
    """Singleton registry for all device configurations."""
    _instance = None
    _configs: Dict[str, Any] = {}
    _defaults: Dict[str, Any] = {
        "firmware_version": "2.4.1",
        "update_url": "https://firmware.internal/updates",
        "debug_mode": False,
        "auth_required": True,
        "allowed_commands": ["status", "reboot", "config"],
        "max_retries": 3
    }

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._configs = {}
        return cls._instance

    def get_config(self, device_id: str) -> Dict[str, Any]:
        if device_id not in self._configs:
            self._configs[device_id] = copy.deepcopy(self._defaults)
        return self._configs[device_id]

    def get_default(self, key: str) -> Any:
        return copy.deepcopy(self._defaults.get(key))


class ConfigMerger:
    """Deep merges configuration patches into device configs."""

    @staticmethod
    def _resolve_path(obj: dict, path_segments: list) -> tuple:
        """Walk the object tree, returning (parent, final_key)."""
        current = obj
        for segment in path_segments[:-1]:
            if segment not in current:
                current[segment] = {}
            current = current[segment]
            if not isinstance(current, dict):
                raise ValueError("Path traversal hit non-dict value")
        return current, path_segments[-1]

    @staticmethod
    def merge(target: dict, patch: dict, path_prefix: str = "") -> dict:
        """Recursively merge patch into target config dict.

        Supports dotted-path keys for nested updates:
          {"network.dns.primary": "8.8.8.8"}
        """
        for key, value in patch.items():
            # Handle dotted path notation
            if '.' in key:
                segments = key.split('.')
                parent, final_key = ConfigMerger._resolve_path(target, segments)
                if isinstance(value, dict) and isinstance(parent.get(final_key), dict):
                    ConfigMerger.merge(parent[final_key], value)
                else:
                    parent[final_key] = value
            elif isinstance(value, dict) and isinstance(target.get(key), dict):
                ConfigMerger.merge(target[key], value, path_prefix + key + ".")
            else:
                target[key] = value
        return target


class FirmwareConfigHandler:
    """Async handler for incoming configuration update messages."""

    def __init__(self):
        self.registry = DeviceRegistry()
        self.merger = ConfigMerger()
        self._update_lock = asyncio.Lock()
        self._pending_updates: asyncio.Queue = asyncio.Queue()

    def _sanitize_key(self, key: str) -> bool:
        """Validate configuration key names."""
        forbidden_chars = [';', '&', '|', '$', '`', '\\', '/']
        return not any(c in key for c in forbidden_chars)

    def _validate_key_allowed(self, key: str) -> bool:
        """Check key is in the allowlist of configurable parameters."""
        segments = key.split('.') if '.' in key else [key]
        return all(seg in _ALLOWED_CONFIG_KEYS for seg in segments)

    def _validate_patch(self, patch: dict, check_immutable: bool = True) -> bool:
        """Validate all keys in the patch recursively."""
        for key, value in patch.items():
            if not self._sanitize_key(key):
                return False
            if not self._validate_key_allowed(key):
                return False
            # Block modification of security-critical keys
            segments = key.split('.') if '.' in key else [key]
            if check_immutable and any(seg in _IMMUTABLE_KEYS for seg in segments):
                return False
            # Validate nested dicts recursively
            if isinstance(value, dict):
                if not self._validate_patch(value, check_immutable):
                    return False
        return True

    async def handle_config_update(self, device_id: str, payload: bytes) -> Dict[str, Any]:
        """Process an incoming config update message."""
        try:
            message = json.loads(payload)
        except json.JSONDecodeError:
            return {"status": "error", "reason": "invalid_json"}

        if not isinstance(message, dict):
            return {"status": "error", "reason": "expected_object"}

        patch = message.get("config", {})
        if not isinstance(patch, dict):
            return {"status": "error", "reason": "config_must_be_object"}

        if not self._validate_patch(patch):
            return {"status": "error", "reason": "invalid_or_forbidden_key"}

        async with self._update_lock:
            config = self.registry.get_config(device_id)
            self.merger.merge(config, patch)

        return {"status": "ok", "device_id": device_id}

    async def execute_command(self, device_id: str, command: str,
                              authenticated: bool = False) -> Dict[str, Any]:
        """Execute a device command if authorized."""
        config = self.registry.get_config(device_id)

        if config.get("auth_required", True):
            # Enforce authentication. In production, 'authenticated' would be
            # the result of verifying a JWT/certificate for this device.
            if not authenticated:
                return {"status": "denied", "reason": "authentication_required"}

        allowed = config.get("allowed_commands", [])
        if command not in allowed:
            return {"status": "denied", "reason": "command_not_allowed"}

        if command == "status":
            return {"status": "ok", "firmware": config.get("firmware_version")}
        elif command == "reboot":
            return {"status": "ok", "action": "rebooting"}
        elif command == "config":
            # Return a copy, not the live config
            return {"status": "ok", "config": copy.deepcopy(config)}

        return {"status": "error", "reason": "unknown_command"}


async def main():
    handler = FirmwareConfigHandler()

    # Simulate normal config update
    result = await handler.handle_config_update(
        "device-001",
        json.dumps({"config": {"network.dns.primary": "8.8.8.8"}}).encode()
    )
    print(f"Config update: {result}")

    # Execute command (authenticated in this simulation)
    result = await handler.execute_command("device-001", "status", authenticated=True)
    print(f"Command result: {result}")


if __name__ == "__main__":
    asyncio.run(main())
